package com.reviewbetterbonia.app.ui.auth;
import android.content.Context;
import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;import androidx.annotation.Nullable;import com.reviewbetterbonia.app.MainActivity;import com.reviewbetterbonia.app.ui.*;

import java.security.MessageDigest;
import java.util.Locale;

public class AuthFragment extends BaseFragment{private final boolean register;public AuthFragment(boolean r){register=r;}
 @Nullable public View onCreateView(LayoutInflater i,ViewGroup c,Bundle b){
  Context x=requireContext();LinearLayout p=Ui.page(x);TextView h=Ui.heading(x,register?"Create your account":"Welcome back");Ui.add(p,h,Ui.dp(x,42));Ui.add(p,Ui.muted(x,register?"Set up your profile and start reviewing.":"Log in to continue your progress.",14),Ui.dp(x,35));EditText name=null;if(register){name=new EditText(x);name.setHint("Username");name.setSingleLine();Ui.add(p,name,Ui.dp(x,55));}EditText email=new EditText(x);email.setHint("Email");email.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);email.setSingleLine();Ui.add(p,email,Ui.dp(x,55));EditText pass=new EditText(x);pass.setHint("Password");pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);pass.setSingleLine();Ui.add(p,pass,Ui.dp(x,55));Ui.addWeight(p,new Space(x));Button go=Ui.button(x,register?"Create account":"Log in",true);Ui.add(p,go,Ui.dp(x,56));Ui.add(p,Ui.gap(x,8),Ui.dp(x,8));Button back=Ui.button(x,"Back",false);back.setOnClickListener(v->requireActivity().getSupportFragmentManager().popBackStack());Ui.add(p,back,Ui.dp(x,52));TextView status=Ui.muted(x,"",13);Ui.add(p,status,Ui.dp(x,50));final EditText userName=name;go.setOnClickListener(v->{String e=email.getText().toString().trim(),pw=pass.getText().toString();if(e.isEmpty()||pw.isEmpty()||(register&&(userName==null||userName.getText().toString().trim().isEmpty()))){status.setText("Please complete all required fields.");return;}go.setEnabled(false);if(app().isOffline()){String hashed=hash(pw);if(register){app().local.setOfflineMode(true);app().local.setDemoAccount(userName.getText().toString().trim(),e,hashed);app().signIn(userName.getText().toString().trim(),e,"local","student",0);app().clearAndShowHome();}else if(app().local.demoExists(e)&&app().local.demoPasswordMatches(hashed)){app().local.setOfflineMode(true);app().signIn(app().local.demoUsername(),e,"local","student",0);app().clearAndShowHome();}else{status.setText("Demo account not found or password is incorrect.");go.setEnabled(true);}return;}if(register){app().firebase.register(userName.getText().toString().trim(),e,pw,(ok, msg, uid, nameFound, role, r)->{go.setEnabled(true);if(!ok){if(msg.toLowerCase(Locale.US).contains("network")||msg.toLowerCase(Locale.US).contains("host")||msg.toLowerCase(Locale.US).contains("connection")||msg.toLowerCase(Locale.US).contains("firebase")){app().local.setOfflineMode(true);String hashed=hash(pw);app().local.setDemoAccount(userName.getText().toString().trim(),e,hashed);app().signIn(userName.getText().toString().trim(),e,"local","student",0);app().clearAndShowHome();return;}status.setText(msg);return;}app().signIn(nameFound,e,uid,role,r);app().clearAndShowHome();});}else{app().firebase.login(e,pw,(ok, msg, uid, nameFound, role, r)->{go.setEnabled(true);if(!ok){if(msg.toLowerCase(Locale.US).contains("network")||msg.toLowerCase(Locale.US).contains("host")||msg.toLowerCase(Locale.US).contains("connection")||msg.toLowerCase(Locale.US).contains("firebase")){app().local.setOfflineMode(true);String hashed=hash(pw);if(app().local.demoExists(e)&&app().local.demoPasswordMatches(hashed)){app().signIn(app().local.demoUsername(),e,"local","student",0);app().clearAndShowHome();return;}else{app().local.setDemoAccount(e.split("@")[0],e,hashed);app().signIn(e.split("@")[0],e,"local","student",0);app().clearAndShowHome();return;}}status.setText(msg);return;}app().signIn(nameFound,e,uid,role,r);app().clearAndShowHome();});}});return p;}
 private String hash(String s){try{byte[] b= MessageDigest.getInstance("SHA-256").digest(s.getBytes("UTF-8"));StringBuilder x=new StringBuilder();for(byte v:b)x.append(String.format(Locale.US,"%02x",v));return x.toString();}catch(Exception e){return s;}}
}
